import math

def count_divisors(m):
    """Calculates the number of positive divisors of m, tau(m)."""
    if m <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            if i * i == m:
                count += 1
            else:
                count += 2
    return count

def check_condition(n):
    """Checks if n = tau(n^12)."""
    # We need to handle the calculation of n^12 carefully if n is large, 
    # but since n <= 500, n^12 might be very large.
    # 500^12 = (5 * 10^2)^12 = 5^12 * 10^24, which is huge.
    # Direct calculation of n^12 is not feasible with standard integer types 
    # if we rely on the standard divisor counting method on the number itself.

    # It is much better to use the prime factorization method.

    if n == 1:
        return True # 1 = tau(1^12) = tau(1) = 1

    # Prime factorization of n
    temp_n = n
    factors = {}
    d = 2
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    # Calculate tau(n^12)
    # If n = p1^a1 * p2^a2 * ..., then n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    tau_n_12 = 1
    for exponent in factors.values():
        tau_n_12 *= (12 * exponent + 1)

    return n == tau_n_12

