import math

def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_n_12(n):
    """
    Calculates tau(n^12) based on the prime factorization of n.
    If n = p1^e1 * p2^e2 * ..., then tau(n^12) = (12*e1 + 1) * (12*e2 + 1) * ...
    """
    if n == 1:
        return 1

    factors = prime_factorization(n)
    tau_n_12 = 1
    for exponent in factors.values():
        tau_n_12 *= (12 * exponent + 1)
    return tau_n_12

solutions_to_check = [1, 13, 25, 325]
verification_results = {}

print("--- Independent Verification of Solutions ---")
for n in solutions_to_check:
    tau_val = calculate_tau_n_12(n)
    is_solution = (n == tau_val)
